//! DEV-355 regtest acceptance: a P2PKH address generated by
//! `LotusAddress::from_hash`/`from_script` (the node/xpi-ts full-script
//! form) must validate on a regtest lotusd v12 node and be usable as a
//! mining payout target (`generatetoaddress`).
//!
//! This test is `#[ignore]`d so it never runs in the default `cargo test`.
//! Run it with the prebuilt lotusd:
//!
//! ```sh
//! CC=gcc-13 cargo +1.99.0 test -p bitcoinsuite-core \
//!     --test test_lotusaddress_regtest -- --ignored --nocapture
//! ```
//!
//! Env overrides:
//! - `LOTUSD_BIN`: lotusd binary (default: the sibling `../lotusd` checkout)
//! - `DEV355_RPC_PORT`: RPC port base (default: 40400 + pid % 2000)

use bitcoinsuite_core::{ecc::Ecc, Hashed, LotusAddress, Net, Script, ShaRmd160, LOTUS_PREFIX};
use bitcoinsuite_ecc_secp256k1::EccSecp256k1;
use serde_json::{json, Value};
use std::{
    io::{Read, Write},
    net::TcpStream,
    path::PathBuf,
    process::{Child, Command, Stdio},
    time::{Duration, Instant},
};

const RPC_USER: &str = "dev355";
const RPC_PASSWORD: &str = "dev355-regtest-password";
/// Default relative to the workspace root; override with `LOTUSD_BIN`.
const DEFAULT_LOTUSD_BIN: &str = "../lotusd/build-clang/src/lotusd";

/// Locate the lotusd binary: `LOTUSD_BIN`, then the sibling checkout from
/// the workspace root or the crate root.
fn lotusd_bin() -> String {
    if let Ok(path) = std::env::var("LOTUSD_BIN") {
        return path;
    }
    for candidate in [DEFAULT_LOTUSD_BIN, "../../lotusd/build-clang/src/lotusd"] {
        if std::path::Path::new(candidate).exists() {
            return candidate.to_string();
        }
    }
    panic!("lotusd not found; set LOTUSD_BIN or build the sibling ../lotusd checkout");
}

/// Kills the node and removes the temp datadir even when assertions fail.
struct NodeGuard {
    child: Child,
    datadir: PathBuf,
}

impl Drop for NodeGuard {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let _ = std::fs::remove_dir_all(&self.datadir);
    }
}

fn base64(input: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(input.len().div_ceil(3) * 4);
    for chunk in input.chunks(3) {
        let b = [
            chunk[0],
            *chunk.get(1).unwrap_or(&0),
            *chunk.get(2).unwrap_or(&0),
        ];
        let n = u32::from_be_bytes([0, b[0], b[1], b[2]]);
        out.push(ALPHABET[(n >> 18) as usize & 0x3f] as char);
        out.push(ALPHABET[(n >> 12) as usize & 0x3f] as char);
        out.push(if chunk.len() > 1 {
            ALPHABET[(n >> 6) as usize & 0x3f] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            ALPHABET[n as usize & 0x3f] as char
        } else {
            '='
        });
    }
    out
}

fn rpc(port: u16, method: &str, params: Value) -> Result<Value, String> {
    let body = json!({
        "jsonrpc": "1.0",
        "id": "dev355",
        "method": method,
        "params": params,
    })
    .to_string();
    let auth = base64(format!("{RPC_USER}:{RPC_PASSWORD}").as_bytes());
    let request = format!(
        "POST / HTTP/1.1\r\n\
         Host: 127.0.0.1:{port}\r\n\
         Authorization: Basic {auth}\r\n\
         Content-Type: application/json\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\
         \r\n\
         {}",
        body.len(),
        body
    );
    let mut stream = TcpStream::connect(("127.0.0.1", port))
        .map_err(|err| format!("RPC {method}: connect failed: {err}"))?;
    stream
        .set_read_timeout(Some(Duration::from_secs(60)))
        .map_err(|err| format!("RPC {method}: set_read_timeout: {err}"))?;
    stream
        .write_all(request.as_bytes())
        .map_err(|err| format!("RPC {method}: write failed: {err}"))?;
    let mut raw = Vec::new();
    stream
        .read_to_end(&mut raw)
        .map_err(|err| format!("RPC {method}: read failed: {err}"))?;
    let text = String::from_utf8(raw).map_err(|err| format!("RPC {method}: non-utf8: {err}"))?;
    let body = text
        .split("\r\n\r\n")
        .nth(1)
        .ok_or_else(|| format!("RPC {method}: no HTTP body in {text:?}"))?;
    let value: Value =
        serde_json::from_str(body).map_err(|err| format!("RPC {method}: bad json: {err}"))?;
    if let Some(error) = value.get("error") {
        if !error.is_null() {
            return Err(format!("RPC {method} error: {error}"));
        }
    }
    value
        .get("result")
        .cloned()
        .ok_or_else(|| format!("RPC {method}: missing result"))
}

#[test]
#[ignore]
fn test_lotusaddress_regtest_validateaddress() -> Result<(), Box<dyn std::error::Error>> {
    // Library-generated regtest P2PKH address (node/xpi-ts full-script form)
    let ecc = EccSecp256k1::default();
    let seckey = ecc.seckey_from_array([1; 32])?;
    let pubkey = ecc.derive_pubkey(&seckey);
    let pubkey_hash = ShaRmd160::digest(pubkey.array().into());
    let p2pkh_script = Script::p2pkh(&pubkey_hash);

    let from_hash_addr = LotusAddress::from_hash(LOTUS_PREFIX, Net::Regtest, pubkey_hash.clone());
    let from_script_addr = LotusAddress::from_script(LOTUS_PREFIX, Net::Regtest, &p2pkh_script)?;
    assert_eq!(
        from_hash_addr.as_str(),
        from_script_addr.as_str(),
        "from_hash and from_script must generate the same address"
    );
    let address = from_hash_addr.as_str().to_string();
    println!("library-generated regtest P2PKH address: {address}");
    println!("expected script: {}", p2pkh_script.hex());
    assert_eq!(
        address, "lotusR16PSJLqasHgB8GqFFzCqpJGH3Bpgh399zfuDxUJcn",
        "must match the known node-valid vector"
    );

    let lotusd_bin = lotusd_bin();
    let rpc_port: u16 = std::env::var("DEV355_RPC_PORT")
        .ok()
        .and_then(|port| port.parse().ok())
        .unwrap_or(40400 + (std::process::id() % 2000) as u16);
    let p2p_port = rpc_port + 1;
    let datadir = std::env::temp_dir().join(format!("dev355-regtest-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&datadir);
    std::fs::create_dir_all(&datadir)?;

    let child = Command::new(&lotusd_bin)
        .args([
            "-regtest",
            &format!("-datadir={}", datadir.display()),
            "-server",
            &format!("-rpcuser={RPC_USER}"),
            &format!("-rpcpassword={RPC_PASSWORD}"),
            &format!("-rpcport={rpc_port}"),
            &format!("-port={p2p_port}"),
            "-nolisten",
        ])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()?;
    let _node = NodeGuard {
        child,
        datadir: datadir.clone(),
    };

    // Wait for the RPC interface
    let start = Instant::now();
    loop {
        match rpc(rpc_port, "getblockcount", json!([])) {
            Ok(_) => {
                println!("node up ({}s)", start.elapsed().as_secs());
                break;
            }
            Err(_) if start.elapsed() < Duration::from_secs(120) => {
                std::thread::sleep(Duration::from_millis(500));
            }
            Err(err) => panic!("node RPC did not come up within 120s: {err}"),
        }
    }

    let validated = rpc(rpc_port, "validateaddress", json!([&address]))?;
    assert_eq!(
        validated["isvalid"].as_bool(),
        Some(true),
        "node rejected library-generated address: {validated}"
    );
    println!("validateaddress: {validated}");

    // Observation (not asserted): the legacy bare-hash form this library
    // used to emit is rejected by lotusd v12's XAddress::Parse.
    let legacy = LotusAddress::from_hash_legacy(LOTUS_PREFIX, Net::Regtest, pubkey_hash);
    let legacy_validated = rpc(rpc_port, "validateaddress", json!([legacy.as_str()]))?;
    println!(
        "legacy bare-hash address {} validateaddress: {legacy_validated}",
        legacy.as_str()
    );

    // Mine one block to the address; its coinbase must pay to the exact script
    let generated = rpc(rpc_port, "generatetoaddress", json!([1, address.as_str()]))?;
    assert_eq!(generated.as_array().map(Vec::len), Some(1));
    let block_hash = generated[0].as_str().unwrap().to_string();
    let block = rpc(rpc_port, "getblock", json!([block_hash, 2]))?;
    let coinbase = &block["tx"][0];
    let vouts = coinbase["vout"]
        .as_array()
        .ok_or("coinbase has no vout array")?;
    let (vout_idx, script_hex) = vouts
        .iter()
        .enumerate()
        .find(|(_idx, vout)| vout["scriptPubKey"]["type"].as_str() != Some("nulldata"))
        .map(|(idx, vout)| {
            (
                idx as u32,
                vout["scriptPubKey"]["hex"].as_str().unwrap().to_string(),
            )
        })
        .ok_or("no spendable coinbase vout")?;
    assert_eq!(
        script_hex,
        p2pkh_script.bytecode().hex(),
        "coinbase must pay to the library address's script"
    );
    println!("coinbase vout {vout_idx} paid to the address's script");

    Ok(())
}
